// Generated by cockpit/build.mjs from cockpit/src. Do not edit.
//
// These are the cockpit's pure functions, tested in node — see cockpit/README.md. They are
// globals here because the page is one classic script; they are modules there because a
// function that cannot be imported cannot be tested except by reimplementing it, and a
// reimplementation agrees with the code right up until one of them changes.

// ── ago.mjs ──
// How long ago, in the words the board uses.
//
// **Formatted here rather than on the server**, and the reason is that the stream stopped re-sending
// a box that only got older. Change detection ignores the clock-derived fields — a box's age moves
// every second whether or not anything happened to it, and leaving it in made every box change on
// every tick — so a server-formatted string would freeze between real changes and a fleet that had
// been quiet for ten minutes would say "2m ago" for ever.
//
// The server sends `age_secs`: the age **at the moment of the observation**. The client knows when
// it received it. So the age is that plus the time since, recomputed on a timer that costs nothing
// and needs no traffic at all.
//
// One formatter, in one language. It was `util::ago` in Rust; two that can disagree is the shape
// §11.7 exists to end, and this is the one the person reads.

// `secs` may be null — `age_secs` is absent when a box's `lastSeen` is unparseable or missing.
// "We do not know" and "just now" are different things and this is the field that says so, so it
// renders as `?` exactly as the server's did, and never as `0s ago`.
function ago(secs) {
  if (secs === null || secs === undefined || Number.isNaN(secs)) return "?";
  const s = Math.max(0, Math.floor(secs));
  if (s < 60) return `${s}s ago`;
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  return `${Math.floor(s / 86400)}d ago`;
}

// A row's age now: what it was when it was observed, plus how long ago that was.
//
// `sinceMs` is how long the row has been held, in milliseconds. Clamped at zero, because a clock
// that steps backwards should make a row look freshly seen rather than make it say `-3s ago`.
function ageNow(secs, sinceMs) {
  if (secs === null || secs === undefined || Number.isNaN(secs)) return "?";
  return ago(secs + Math.max(0, Math.floor((sinceMs || 0) / 1000)));
}

// ── announce.mjs ──
// What to announce, and on which channel. The decision only — the speaking and the notifying are
// the caller's, because a function that reaches for `speechSynthesis` is one that has to be mocked
// rather than called.
//
// **Voice and alerts are independent switches**, and that is the property this exists to keep. They
// were once one condition, and turning alerts off silenced the voice — a bug that is invisible in
// the source unless you are looking for it, which is exactly why asserting it by matching the page's
// text was standing in for a test.
//
// Two outputs from one rule, so they cannot drift into disagreeing about what is worth interrupting
// somebody for.
//
// **The speech grammar lives here too, and did not at first.** When this module was extracted the
// page kept `sayName`, `forSpeech`, `VERB` and `utteranceFor`, and `sentenceFor` was written fresh —
// so the standing-debt channel quietly stopped saying what a box was asking for and started reading
// box names literally. `proj s 6 wants permission. run rm -rf build` became `proj-s6 needs you`. That
// is the sentence that decides whether somebody gets up, and every one of these functions is a rule
// learned out loud. `docs/delivery.md` §5: the architecture is the easy half; the grammar is the
// product. So the grammar is here, where it is tested in node, and there is one of it.

// How long a person must have been away before anything speaks. Being at the board is not being
// interrupted; announcing what is on screen in front of them is a nag.
const OWED_GRACE_MS = 20_000;

// Past a couple, a count is all anybody can act on — and six banners stacked on a lock screen is the
// same nag wearing a different hat.
const NAME_AT_MOST = 2;

// Decide what this tick should announce.
//
// `fresh` is the boxes newly owed that have not been announced yet — the caller keeps that
// bookkeeping, because it is state and this is not. Returns what to do, never what was done.
// `opts.groupOf` maps a box's state to its board group, and it is an argument rather than an import
// because `cockpit/build.mjs` concatenates these modules and refuses one that imports — what belongs
// here is leaf functions with every input passed in. The sentence needs it: what a box is asking is
// different from that it finished or that it broke.
function announcementsFor(fresh, opts) {
  const {
    voiceOn = false,
    alertsOn = false,
    awayForMs = 0,
    speakingAlready = false,
    groupOf = null,
  } = opts || {};
  const quiet = { notes: [], say: "", beep: false };

  // Nothing to announce *with*. The caller keeps its backlog rather than clearing it, so turning a
  // channel on tells you what you missed instead of starting from silence — which is why this
  // returns "say nothing" rather than "there is nothing".
  if (!voiceOn && !alertsOn) return quiet;
  if (awayForMs < OWED_GRACE_MS) return quiet;
  if (!fresh || !fresh.length) return quiet;
  // Another sentence is being read on this tick. Let it stand alone and say this on the next one.
  if (speakingAlready) return quiet;

  // A notification is **read**, so it carries the box's real name — the string on the board row and
  // in the tag the browser dedupes on. Only the spoken channel gets `sayName`. The two look like the
  // same string and are not: one is an identifier you click, the other is something said out loud.
  //
  // It gets the verb, though, and for the reason the sentence does: `web-main is waiting` and
  // `web-main wants permission` are two different reasons to pick the phone up and `web-main needs
  // you` is neither. This said "needs you" for a while and `noteFor` sat in the page, defined and
  // called by nothing — the same regression as the spoken one, in the channel where the text is all
  // there is.
  const notes = !alertsOn
    ? []
    : fresh.length <= NAME_AT_MOST
      ? fresh.map(b => ({
          body: `${b.name} ${noteFor(b, groupOf ? groupOf(b.state) : "attn")}`,
          tag: b.name,
        }))
      : [{ body: `${fresh.length} boxes need you`, tag: "skein-owed" }];

  return {
    notes,
    // **Independent.** `voiceOn` is read on its own and not alongside `alertsOn`; a reader who has
    // to check both to know whether the voice speaks is reading the bug this had.
    say: voiceOn ? sentenceFor(fresh, groupOf) : "",
    beep: alertsOn && notes.length > 0,
  };
}

// The sentence, for however many boxes.
//
// One box gets the whole utterance — what it is asking, in the words that distinguish "wants
// permission" from "needs you to sign in" — because with one box there is a decision to describe and
// describing it is the difference between getting up and not. Two get named, spoken. Past that a
// list of names read aloud is not something anybody hears, so it is a count.
function sentenceFor(fresh, groupOf) {
  if (!fresh || !fresh.length) return "";
  if (fresh.length === 1) {
    // No `groupOf` means the caller could not say which group this is in, and every caller that
    // cannot is asking about a box that is owed — which is what `attn` is.
    return utteranceFor(fresh[0], groupOf ? groupOf(fresh[0].state) : "attn");
  }
  if (fresh.length <= NAME_AT_MOST) {
    return `${fresh.map(b => sayName(b.name)).join(" and ")} need you`;
  }
  return `${fresh.length} boxes need you`;
}

// A box name is written to be read, not spoken: `example-report-parsing` said literally is three
// words run together, and `PROJ-S6` comes out as a word. Hyphens and underscores become pauses, and
// a letter/digit boundary gets a space so "S6" is "S 6" rather than a syllable.
const sayName = n => String(n || "").replace(/[-_]+/g, " ").replace(/([A-Za-z])(\d)/g, "$1 $2");

// What a box that just stopped is actually asking. The kind matters more than the words: "wants
// permission" and "needs you to sign in" want completely different things from you, and a single
// "needs a decision" for both is what makes you go and look — which is the cost this is removing.
const VERB = {
  permission: "wants permission",
  question: "asks",
  trust: "needs you to trust the folder",
  auth: "needs you to sign in",
};

// Headlines are agent prose, and agent prose is full of things that are unbearable out loud: absolute
// paths, URLs, backticked identifiers, markdown. Speaking `/boxes/example-work/tree/src/place.rs`
// costs eight seconds and communicates nothing — the basename communicates all of it. This is the
// single biggest difference between a voice that helps and one that gets muted.
function forSpeech(text) {
  let s = String(text || "");
  s = s.replace(/`+/g, " ");                                  // code spans: the ticks are noise
  s = s.replace(/\*\*?|__|~~/g, " ");                          // markdown emphasis
  s = s.replace(/https?:\/\/\S+/g, " a link ");                // nobody wants a URL read out
  // A path becomes its basename. Deliberately not every token with a slash in it — "and/or" and
  // "24/7" are words, not paths — so a token qualifies only by looking like one: rooted at /, ~/ or
  // ./, or ending in something with a file extension.
  s = s.replace(/\S+/g, token => {
    if (!token.includes("/")) return token;
    const last = token.split("/").filter(Boolean).pop() || token;
    const isPath = /^[~.]?\//.test(token) || /^[\w.-]+\.[A-Za-z]{1,8}$/.test(last);
    return isPath ? last : token;
  });
  s = s.replace(/\s+/g, " ").trim();
  // Close the gap the strippers left. A backtick becomes a space so `a`+`b` does not fuse into one
  // word — but a span that ended right before punctuation then reads as "build ?", and a speech
  // engine hears that space as a pause in the wrong place.
  s = s.replace(/\s+([,.;:!?])/g, "$1");
  // One breath. A long ask is a reason to look, not something to recite — the row on the board has
  // the full text, and cutting at a sentence boundary keeps what was said grammatical.
  if (s.length > 160) {
    const cut = s.slice(0, 160);
    const stop = Math.max(cut.lastIndexOf(". "), cut.lastIndexOf("? "), cut.lastIndexOf("! "));
    s = (stop > 60 ? cut.slice(0, stop + 1) : cut.replace(/\s+\S*$/, "")) + "…";
  }
  return s;
}

// One box, said in full. `group` is the board group it is in — the caller has it, and passing it
// keeps this a leaf function.
function utteranceFor(b, group) {
  const name = sayName(b.name);
  const head = forSpeech(b.headline);
  if (group === "error") return head ? `${name} hit an error. ${head}` : `${name} hit an error.`;
  if (group === "done") return `${name} finished.`;
  // A box that ended its turn. Distinct from `attn` on purpose: nothing is blocking it, it has said
  // its piece and stopped, so "needs a decision" would overstate what it is asking for.
  if (group === "waiting") return head ? `${name} is waiting. ${head}` : `${name} is waiting.`;
  const verb = VERB[b.blocked_kind] || (b.pause === "proceed" ? "wants to continue" : "needs a decision");
  // Trust and auth are self-explaining — appending the box's last words to them adds length and no
  // information, because the ask is the state itself rather than anything the agent said.
  if (!head || b.blocked_kind === "trust" || b.blocked_kind === "auth") return `${name} ${verb}.`;
  return `${name} ${verb}. ${head}`;
}

// The same thing in a banner's worth of words — no name, because the notification puts it in front.
//
// Shorter than `utteranceFor` on purpose: a notification is glanced at on a lock screen and the
// headline that helps in a spoken sentence is length that gets it dismissed unread.
function noteFor(b, group) {
  if (group === "error") return "hit an error";
  if (group === "waiting") return "is waiting";
  return VERB[b.blocked_kind] || (b.pause === "proceed" ? "wants to continue" : "needs a decision");
}

// ── away.mjs ──
// What the away digest lists, from the server's journal of state changes (`GET /api/away`).
//
// The journal is the server's, and so is the mark it is read from (`src/stream.rs`): a delta kept in
// a tab's memory dies on reload and disagrees with every other tab, which is why the page no longer
// computes one of its own. What is left here is only the reading — several moments for one box
// become one line about where it ended up.
//
// `groupOf` is an argument rather than an import because this module is concatenated into the page
// beside `groups.mjs` (see cockpit/build.mjs), and a leaf takes its dependencies as arguments.

// What a box that ENDED UP in each group did while you were away, and how high it sorts: what needs
// you first, then what finished, then what merely moved.
const SAID = {
  attn: [0, "now needs a decision"],
  waiting: [0, "is waiting for your next instruction"],
  error: [0, "hit an error"],
  done: [1, "finished"],
  working: [3, "went back to work"],
  ended: [2, "ended"],
  idle: [3, "went idle"],
  stale: [2, "stopped reporting"],
};

function awayItems(moments, boxes, groupOf) {
  const now = new Map((boxes || []).map(b => [b.name, b]));
  // Oldest first, as the server keeps them, so the first moment holds where a box started from and
  // the last where it is now.
  const by = new Map();
  for (const m of moments || []) {
    const seen = by.get(m.name);
    if (seen) seen.to = m.to;
    else by.set(m.name, { from: m.from, to: m.to });
  }
  const items = [];
  for (const [name, { from, to }] of by) {
    const box = now.get(name);
    if (!box) {
      items.push({ pri: 2, name, kind: "gone", text: "left the board (destroyed or merged)" });
      continue;
    }
    const g = groupOf(to);
    // A box that went somewhere and came back is where you left it, and saying otherwise is noise.
    if (g === groupOf(from)) continue;
    const [pri, text] = SAID[g] || SAID.stale;
    const headline = box.headline ? ` — ${box.headline}` : "";
    items.push({ pri, name, kind: g, text: text + (pri === 0 ? headline : "") });
  }
  items.sort((a, b) => a.pri - b.pri || a.name.localeCompare(b.name));
  return items;
}

// ── change.mjs ──
// The change view's decisions (§11.1): what a module's note is worth showing, and what a signal's
// count is allowed to say.
//
// The job is **not** reading a diff. What matters is which modules changed, how the design
// decomposes now, and being able to drill to code when something warrants it — mostly it is not
// read at all. So these are the three judgements that turn `shape::of_diff`'s answer into a screen,
// and each is here rather than in the page because each is a rule somebody could get wrong quietly.

// The one-line summary above the modules: how many moved, and how much.
//
// Summed from the modules rather than taken from a field, because there is no such field — and a
// count computed in two places is the disagreement §11.7 exists to end.
function summaryOf(modules) {
  const list = modules || [];
  return {
    modules: list.length,
    added: list.reduce((n, m) => n + (m.added || 0), 0),
    removed: list.reduce((n, m) => n + (m.removed || 0), 0),
  };
}

// A module's standing note, and what to say when there is not one worth showing.
//
// **A stale note is not shown.** Its freshness is keyed to the commit the module was at, and a
// description of code that has since changed is worse than no description because it reads exactly
// like a current one. The three states are three different offers: read it, rewrite it, write one.
function noteOf(module) {
  const m = module || {};
  if (m.note_state === "fresh" && m.note) return { state: "fresh", text: m.note };
  if (m.note_state === "stale") return { state: "stale", text: "its note is older than the code — rewrite it before trusting it" };
  return { state: "absent", text: "no note yet" };
}

// What a contract signal's count says, or nothing at all.
//
// **Absent and zero are different answers and must read differently.** `mentions` is missing when
// the signal's detector could not name a symbol — a deleted file, a rename — and "0 mentions" would
// read as "nothing uses this", which is the opposite of "we did not look". Zero is kept when it is
// real: a symbol the change introduces is named nowhere in the base, which is worth seeing.
//
// "mentions", not "call sites": the count is lines of the base tree naming the symbol, and `git
// grep` cannot tell a call from a comment. A reviewer who trusts "12 call sites" and finds four is
// worse off than one who was told what was counted.
function mentionsLabel(signal) {
  const n = signal && signal.mentions;
  if (n === null || n === undefined) return "";
  return `${n} mention${n === 1 ? "" : "s"}`;
}

// Where the shape of a change comes from, for the two ways one can arrive.
//
// One function, because the shape of a change does not depend on whether it came as a pull request
// or as a branch somebody is still working on — the server already serves both from one, and a page
// that decided differently would be a third opinion about the same question.
//
// **The pull-request URL is spelled the way the router spells it, not the way the feature reads.**
// A pull request's shape is one of the review routes — `/api/repos/:id/review/:number/…`, beside
// `diff` and `act` — and `:id` is the registered repo's id, which is exactly what a queue row
// carries in `repo` (`queue.rs:233`). This function shipped asking `/api/pr/:repo/:n/shape`, a route
// nothing has ever registered, so from `c5ddc46` onward every click on a pull request 404'd and the
// page reported its own "the change could not be read" (SKEIN-246). The tests that let that survive
// asserted this string; what asserts it now is the router's own table — `cockpit_routes` in
// `bin/skein-server/main.rs` scans this bundle against it, and `the_change_view_asks_a_url_this_router_answers`
// runs this function and matches its answer.
function shapeUrl(row) {
  const r = row || {};
  if (r.source === "box") return `/api/boxes/${encodeURIComponent(r.name)}/shape`;
  if (r.source === "pull-request") {
    const number = String(r.name || "").replace(/^#/, "");
    if (!r.repo || !number) return "";
    return `/api/repos/${encodeURIComponent(r.repo)}/review/${encodeURIComponent(number)}/shape`;
  }
  return "";
}

// ── density.mjs ──
// Dense when the fleet is large, comfortable when it is small — §11.7, same components either way.
//
// It is a function of how many rows there are, not of the window: a fleet of three is comfortable on
// a laptop and on a wall display, and a fleet of forty is a list you scan on both. Tying it to
// viewport width would make the same fleet read differently on two screens, which is the opposite of
// an identity learned once.

const COMFORTABLE = "comfortable";
const DENSE = "dense";

// Where it switches. Twelve rows is about where a page stops being read and starts being scanned —
// and it is one number in one place so that "adaptive" cannot come to mean two components
// disagreeing about what a large fleet is.
const MANY = 12;

const densityFor = rows => ((rows || 0) >= MANY ? DENSE : COMFORTABLE);

// ── filter.mjs ──
// The board's filter, as a function of what it is given.
//
// `foreign:` is the one term that changes WHICH boxes are eligible rather than narrowing them. A
// sandbox skein did not place is not on the board's tick at all any more — it is fetched when
// somebody asks — so the eligible pool is passed in rather than filtered out of the board's rows.

const FOREIGN_TERM = "foreign:";
const wantsForeign = q => (q || "").includes(FOREIGN_TERM);
const withoutForeignTerm = q => (q || "").split(FOREIGN_TERM).join(" ").trim();

// `managed:` is the other half of that pair and it is deliberately NOT the same kind of term.
//
// A managed box — one skein started itself, to review a pull request — is skein's own box in
// skein's own sandbox, and it can get stuck or ask a question like any other. So it is on the board
// by default and `managed:` NARROWS to those rows; it does not reveal them. Hiding them the way
// `foreign:` hides a stranger's sandbox would mean a box spending model calls where nobody can see
// it, which is the one failure a board exists to prevent.
const MANAGED_TERM = "managed:";
const wantsManaged = q => (q || "").includes(MANAGED_TERM);
const withoutManagedTerm = q => (q || "").split(MANAGED_TERM).join(" ").trim();

// Does this row match the words typed? Every word must appear somewhere, so adding one narrows.
function matchesFilter(b, q) {
  if (!q) return true;
  const hay = `${b.name} ${b.branch || ""} ${b.repo || ""} ${b.headline || ""}`.toLowerCase();
  return q.split(/\s+/).filter(Boolean).every(t => hay.includes(t));
}

// Which rows the board draws, for a fleet, a filter, and the foreign rows if any have been fetched.
//
// **`foreign` is an argument.** It used to be module state the function reached out for, which is
// exactly what made this untestable — a pure function is one whose inputs are all in front of you.
//
// Eligibility first, then the text match over what is left, because `foreign:` answers "which boxes"
// and the rest answers "which of those".
function boardRows(all, rawFilter, foreign) {
  const q = (rawFilter || "").trim().toLowerCase();
  const pool = wantsForeign(q) ? (foreign || []) : (all || []);
  // `foreign:` swaps the pool; `managed:` only narrows the one already chosen. A row is never both
  // — a sandbox skein did not place has no placement record, and the purpose is written in that
  // record — so the two terms compose without either having to know about the other.
  const eligible = pool
    .filter(b => (wantsForeign(q) ? b.foreign : !b.foreign))
    .filter(b => (wantsManaged(q) ? !!b.managed : true));
  const text = withoutManagedTerm(withoutForeignTerm(q));
  return text ? eligible.filter(b => matchesFilter(b, text)) : eligible;
}

// ── fleetsize.mjs ──
// The size the fleet sandbox has, measured, for the Fleet pane (the owner, 2026-09-27, R1).
//
// The measured sandbox is the truth. `fleet_memory`, `fleet_cpus` and `fleet_disk` in config.json
// are only what the NEXT create asks sbx for, and sbx fixes a sandbox's size when it is made, so the
// two differ on any fleet whose settings were edited since. The pane shows both, each labelled for
// what it is, and nothing here compares them: a difference is what editing the next size means, not
// a fault.
//
// `r` is `/api/fleet/resources` (`FleetResources`, MiB throughout); `fmt` is the page's mebibyte
// formatter, passed in because these modules are concatenated without imports.
function sandboxSize(r, fmt) {
  if (!r || !r.mem_total) return "";
  return [
    r.cpus ? `${r.cpus} CPUs` : "",
    `${fmt(r.mem_total)} memory`,
    r.disk_total ? `${fmt(r.disk_total)} disk` : "",
  ].filter(Boolean).join(" · ");
}

// ── groups.mjs ──
// Which group a box's state belongs to, and what "owed to you" means.
//
// One place, because it was written out three times and they disagreed: the tab title and the
// needs-you navigation counted `waiting` and both voice paths did not — so the title said "3 need
// you" while the mouth stayed shut, and "read what needs me" answered "nothing needs you" with boxes
// visibly waiting on screen.
const GROUPS = [
  { key: "error", label: "error", match: s => s === "error" },
  { key: "attn", label: "needs you", match: s => ["needs-input", "needs-decision", "blocked"].includes(s) },
  { key: "waiting", label: "waiting", match: s => s === "waiting" },
  { key: "done", label: "done", match: s => s === "done" },
  { key: "working", label: "working", match: s => ["working", "running", "live", "compacting"].includes(s) },
  { key: "ended", label: "ended", match: s => s === "ended" },
  { key: "idle", label: "idle", match: s => s === "idle" },
  { key: "stale", label: "stale", match: s => s === "stale" || s === "unknown" },
];

// An unrecognised state falls to the last group rather than to nothing: a box whose state this page
// has never heard of is a box that is not talking, which is what `stale` means.
const groupOf = s => (GROUPS.find(g => g.match(s)) || GROUPS[GROUPS.length - 1]).key;

// `waiting` is a box that ended its turn and wants your next instruction, which is the most ordinary
// way a box needs you there is.
const NEEDS_YOU = ["error", "attn", "waiting"];

const owedIn = list => list.filter(b => NEEDS_YOU.includes(groupOf(b.state)));

const labelOf = s =>
  ["needs-input", "needs-decision", "blocked"].includes(s) ? "decision" : s === "live" ? "active" : s;

// ── held.mjs ──
// The note beside a Settings control that an environment variable is holding right now.
//
// Said only while it is true (the owner, 2026-09-27). `held` is the server's answer — which fields
// a variable holds, and which variable (`config::held_by_env`) — so a note that is always there,
// true or not, cannot come back: nothing held, nothing said.
//
// A switch can only be held OFF, because an environment variable may only turn things off
// (`config::env_holds_off`); the review model is a value, so any value set holds it.
const SWITCHES = ["pr_workflows", "ai_enrichment", "review_summaries", "box_plugin"];

function heldNote(field, held) {
  const name = held && held[field];
  if (!name || !/^[A-Z0-9_]+$/.test(name)) return "";
  return `${SWITCHES.includes(field) ? "held off by" : "held by"} <code>$${name}</code>`;
}

// ── keys.mjs ──
// Which global shortcut a keystroke is, if any. The decision only — acting on it is the caller's,
// because moving the selection and opening a terminal need a DOM and this does not.
//
// **The typing guard is the whole feature.** A shortcut that steals a keystroke in a text field or a
// live terminal is worse than no shortcut: the agent in that terminal needs Escape, and somebody
// naming a box needs every letter. So the guard comes first, before any match, and it returns
// nothing rather than something harmless — "no shortcut" is the answer, not "a shortcut that does
// nothing".
//
// One table, because a keymap written as a `switch` in the page and a guard beside it is two places
// a key can be handled and one place it can be forgotten.

// What a key means when nothing owns the focus. `null` is "not a shortcut".
const FLEET = {
  Escape: "deselect",
  j: "next",
  ArrowDown: "next",
  k: "previous",
  ArrowUp: "previous",
  Enter: "open",
  o: "open",
  d: "diff",
  "?": "keys",
  "/": "filter",
  "]": "next-needs-you",
  L: "load",
  l: "load",
  "[": "previous-session",
  "}": "next-session",
};

// What a key means while the review pane is the surface (SKEIN-151/159, docs/parity.md §3).
// Consulted INSTEAD of `FLEET` when `where.pane === "review"`, and a miss here does NOT fall
// through to the fleet table: with the pane open, the fleet's `j`/`k`/`↵`/`d`/`]` would move a
// selection BEHIND the pane and `↵` would navigate out of review entirely — worse than dead keys,
// and data-loss-shaped with a composer open. The one deliberate pass-through is `?`, which names
// the fleet's own `keys` action because the key sheet is one surface whichever pane asks for it
// (and `⌘K`/`⌘N` never reach either table — they are decided before the guard).
//
// **One table, and now one mode.** This block used to say the table served two — a queue and a
// reading view of skein's own — with the page dispatching each action by whichever was showing.
// CKP-7 removed the reading view, so `where.pane === "review"` names a single surface and there is
// no second mode for a key to mean something else in. Four entries are deliberate and are stated
// because an odd line is otherwise indistinguishable from a forgotten one:
//   * `m` (merge) is UNBOUND. It is the one act that cannot be undone from this pane, and on a
//     surface used thirty times a day one letter must not land a commit on a base branch. The
//     merge chip, behind its confirm, is the only way.
//   * `a` maps to `rev-approve` and the page refuses it out loud, unconditionally — you cannot
//     approve from a surface that is not showing you the change, and with the reading view gone
//     there is no surface here that does. The refusal lives in the dispatcher, not here, because
//     "this key exists and is refused" is a message, where a missing key would be a fleet leak.
//   * `o` opens the thing HERE, matching the fleet's own `o` → open. What it opens is the ROW:
//     the reading, the verdicts and the composer are all in the expansion. Rebinding it to leave
//     the product would train the wrong reflex; GitHub is the `g h` chord.
//   * `c`, `r`, `]` and `[` addressed hunks and files in the reading view and outlived it. They
//     stay bound, each answering with a sentence, because being in THIS table is what shadows them
//     from `FLEET` (SKEIN-568) — unbinding them would let a keystroke move a selection behind the
//     pane, which is the leak the paragraph above exists to stop.
const REVIEW = {
  Escape: "rev-back",
  ArrowLeft: "rev-back",
  j: "rev-next",
  ArrowDown: "rev-next",
  k: "rev-previous",
  ArrowUp: "rev-previous",
  n: "rev-next-undecided",
  N: "rev-previous-undecided",
  ArrowRight: "rev-into",
  Enter: "rev-open",
  o: "rev-open",
  e: "rev-aside",
  u: "rev-undo",
  "/": "rev-search",
  g: "rev-chord",
  G: "rev-last",
  c: "rev-comment",
  a: "rev-approve",
  r: "rev-request",
  // Shift-R, beside `r`, and a capital because it spends nothing and undoes nothing: it asks skein
  // to read the selected pull request again against the commit that is there now (SKEIN-228). The
  // day's ceiling is on skein's own initiative, never on a person, so this key is never refused.
  R: "rev-reread",
  "]": "rev-next-file",
  "[": "rev-previous-file",
  "?": "keys",
};

// The second key of a `g` chord (`g` then one more). Its own table so the whole decision stays
// here, testable in node — the page remembers only THAT a chord is pending, never what keys mean.
// `g 1`…`g 9` (the nth repo) are matched in code below because nine near-identical lines is where
// a typo hides.
const REVIEW_CHORD = {
  g: "rev-first",
  r: "rev-repo-menu",
  h: "rev-github",
};

// The tab keys, which must work *while you are typing in the agent*, so they are decided apart from
// the tables above (which yield every key to a focused terminal). ⌥ chords only: the browser
// reserves ⌘1-9 and ⌃Tab, and the agents' own composers use ⌥←/⌥→ for word movement — brackets are
// free in all of them. Matched on `code`, since ⌥[ on macOS reports `key` as "“". Keyed by what the
// key sheet prints, so the sheet and the binding are this one table (SKEIN-1187); `⌥1`…`⌥9` are
// matched in code below for the reason `g 1`…`g 9` are.
const TABS = {
  "⌥[": "tab-previous",
  "⌥]": "tab-next",
  "⌥⇧[": "tab-move-left",
  "⌥⇧]": "tab-move-right",
};

// Which tab key an event is, if any — `tab-1`…`tab-9` (the nth tab; past the end is the last), or
// one of TABS.
function tabShortcutFor(event) {
  if (!event || !event.altKey || event.metaKey || event.ctrlKey) return null;
  const digit = /^Digit([1-9])$/.exec(event.code || "");
  if (digit) return `tab-${digit[1]}`;
  const bracket = { BracketLeft: "[", BracketRight: "]" }[event.code];
  if (!bracket) return null;
  return TABS[`⌥${event.shiftKey ? "⇧" : ""}${bracket}`] || null;
}

// `where` is what the caller knows about focus, which is the part that needs a DOM. Passing it in is
// what makes this testable at all.
function shortcutFor(event, where) {
  const { inTerm = false, inField = false, dialogOpen = false, pane = "", pending = "" } = where || {};
  const key = (event && event.key) || "";
  const mod = !!(event && (event.metaKey || event.ctrlKey));

  // ⌘K and ⌘N are deliberately *before* the guard: they open the palette and the new-box dialog, and
  // somebody typing in a field is exactly who wants them. Every browser reserves the same pair, so
  // no field is expected to swallow them.
  if (mod && key.toLowerCase() === "k") return "palette";
  if (mod && key.toLowerCase() === "n") return "new-box";
  // Any other modifier chord belongs to the browser or the terminal, not to the fleet keymap.
  if (mod) return null;

  // A dialog owns its own keys; one that leaks to the fleet keymap moves the selection behind it.
  if (dialogOpen) return key === "Escape" ? "close-dialog" : null;

  // The guard. Nothing below this line may fire while somebody is typing.
  if (inTerm || inField) return null;

  if (pane === "review") {
    // A pending `g` consumes the NEXT key whole: `g 1`…`g 9` is the nth repo in the picker's
    // order, the rest are in REVIEW_CHORD — and an unknown second key ends the chord as nothing
    // rather than as a shortcut, so a fumbled chord costs a keystroke, never an act.
    if (pending === "g") return /^[1-9]$/.test(key) ? `rev-repo-${key}` : REVIEW_CHORD[key] || null;
    // No fall-through past this table (SKEIN-151): `?` keeps working because REVIEW names the
    // fleet's `keys` action itself, and every other fleet key is shadowed while the pane is the
    // surface — a key that reached the fleet map here would move a selection behind the pane.
    return REVIEW[key] || null;
  }

  return FLEET[key] || null;
}

// Every action this can return, so a caller that switches on it can be checked for completeness.
const ACTIONS = [
  ...new Set([
    "palette", "new-box", "close-dialog",
    ...Object.values(FLEET),
    ...Object.values(REVIEW),
    ...Object.values(REVIEW_CHORD),
    ...Object.values(TABS),
    ...Array.from({ length: 9 }, (_, i) => `tab-${i + 1}`),
    ...Array.from({ length: 9 }, (_, i) => `rev-repo-${i + 1}`),
  ]),
];

// ---- the key sheet: Settings → Shortcuts and `?` (SKEIN-1187) --------------------------------
//
// **Rendered from the tables above, not written beside them.** The page kept a second table for the
// sheet, which nothing bound from, and it had drifted: the fleet's `o`, `[`, `}` and the arrow keys
// were bound here and missing there, under a comment saying the two "can't drift". So the sheet is
// built from FLEET, REVIEW, REVIEW_CHORD and TABS, and all a key needs to appear on it is the words
// in SAYS; `keys.test.mjs` holds the sheet equal to what those tables bind.

// What each action does, in the words the sheet prints. Actions that share words share a row, so
// `j`/`↓` and `k`/`↑` are one line and not four.
const SAYS = {
  palette: "command palette",
  "new-box": "new box",
  "close-dialog": "close a dialog",
  keys: "this list",
  deselect: "leave the terminal, back to the board",
  next: "move the selection",
  previous: "move the selection",
  open: "open the selected box's terminal",
  diff: "open its diff",
  filter: "filter the board by name, branch, repo or headline",
  "next-needs-you": "jump to the next box that needs you",
  load: "load by box — which one is using the CPU",
  "previous-session": "previous open session",
  "next-session": "next open session",
  "rev-next": "move the selection (inside an open stack, along its steps)",
  "rev-previous": "move the selection (inside an open stack, along its steps)",
  "rev-next-undecided": "next / previous row you have not decided this session",
  "rev-previous-undecided": "next / previous row you have not decided this session",
  "rev-into": "enter the selected stack",
  "rev-back": "fold the open row, or leave the stack, back at its head",
  "rev-open": "open the selected row — o opens things here; GitHub is g h",
  "rev-aside": "set aside — the row greys in place, u takes it back within 8s",
  "rev-undo": "undo the held act",
  "rev-reread": "read this one again, against the commit that is there now",
  "rev-search": "find a pull request",
  "rev-last": "last row",
  "rev-first": "first row",
  "rev-repo-menu": "the repo picker",
  "rev-github": "open it on GitHub",
  "rev-approve": "refused here, deliberately — you cannot approve from a surface that is not showing you the change; ↵ opens the row, and approve is a chip in it",
  "rev-comment": "says where comment went — a chip on the row",
  "rev-request": "says where request changes went — a chip on the row",
  "rev-next-file": "say where the diff went — g h opens the change on GitHub",
  "rev-previous-file": "say where the diff went — g h opens the change on GitHub",
  "tab-previous": "previous tab",
  "tab-next": "next tab",
  "tab-move-left": "move the current tab left / right",
  "tab-move-right": "move the current tab left / right",
};

// How a key's name prints. Anything not here prints as itself.
const SHOWN = { Escape: "esc", Enter: "↵", ArrowDown: "↓", ArrowUp: "↑", ArrowLeft: "←", ArrowRight: "→" };

// Rows for one table: its keys grouped by the words their actions share, in the table's order.
function rowsOf(table, prefix = []) {
  const rows = new Map();
  for (const [key, action] of Object.entries(table)) {
    const says = SAYS[action];
    if (!says) continue;
    if (!rows.has(says)) rows.set(says, []);
    rows.get(says).push(...prefix, SHOWN[key] || key);
  }
  return [...rows].map(([says, keys]) => [keys, says]);
}

// **The key sheet**, as sections of `[keys, words]` rows. Four sections are the binding tables
// themselves; the last two are said here because they are not skein's to bind — the terminal's own
// keys and a drag — and a sheet that dropped them would leave people guessing at ⌘C.
//
// Written with the Mac's ⌘/⌥/⇧/⌃; `platformKeys` turns them into what another keyboard has on it.
// `mac` decides the one row family whose chord is not a modifier swap: off a Mac a terminal copies
// and pastes on Ctrl+Shift, because a bare Ctrl+C is the interrupt (`copy`/`paste` in settings.js).
function keySheet(mac = true) {
  return [
    { sec: "Anywhere", items: [
      [["⌘K"], SAYS.palette],
      [["⌘N"], SAYS["new-box"]],
      [["?"], SAYS.keys],
      [["esc"], SAYS["close-dialog"]],
    ] },
    { sec: "Fleet", items: rowsOf(FLEET).filter(([keys]) => keys[0] !== "?") },
    { sec: "Review — the queue", items: [
      ...rowsOf(REVIEW).filter(([keys]) => keys[0] !== "?"),
      [["g", "1", "…", "g", "9"], "the nth repo in the picker's order"],
      ...rowsOf(REVIEW_CHORD, ["g"]),
      // The one deliberate absence, LISTED rather than omitted: a sheet that silently lacks `m`
      // reads as a sheet that forgot it. `shortcutFor` returns nothing for it, and a test says so.
      [["m"], "unbound, deliberately — merging cannot be undone from this pane, so one letter must never land a commit on a base branch; the merge chip asks first"],
    ] },
    { sec: "Tabs", items: [
      [["⌥1", "…", "⌥9"], "switch to the nth open tab (⌥9 is always the last)"],
      ...rowsOf(TABS),
      [["drag"], "reorder tabs by dragging one — esc cancels, and the order is remembered"],
    ] },
    { sec: "In a terminal", items: [
      [[mac ? "⌘C" : "⌃⇧C"], "copy the selection"],
      [[mac ? "⌘V" : "⌃⇧V"], "paste"],
      [["⌃C"], "interrupt — goes through to the agent, never intercepted"],
      [[mac ? "⌘V" : "⌃⇧V", "file"], "paste a file, or drag one in, to hand it to the agent"],
    ] },
  ];
}

// Every key the tables bind, by table — what `keys.test.mjs` holds the sheet to, so a key added to
// a table and not to the sheet fails there rather than going undocumented.
function boundKeys() {
  return {
    fleet: Object.keys(FLEET),
    review: Object.keys(REVIEW),
    chord: Object.keys(REVIEW_CHORD),
    tabs: Object.keys(TABS),
  };
}

// ⌘/⌥/⇧/⌃ are Mac glyphs; away from a Mac the same bindings are Ctrl/Alt/Shift (the handlers
// accept either), so print what that keyboard actually has on it. Every place the cockpit names a
// modifier goes through this — the sheet, the footer, the buttons' hints — so a Linux user is not
// told ⌘K on a button and Ctrl+K in the sheet.
function platformKeys(text, mac) {
  return mac ? text
    : String(text).replaceAll("⌘", "Ctrl+").replaceAll("⌃", "Ctrl+").replaceAll("⌥", "Alt+").replaceAll("⇧", "Shift+");
}

// ── links.mjs ──
// Which URLs the cockpit will follow out of text it did not write.
//
// Markdown is rendered from four sources skein does not control — a `.md` file in a box's tree, the
// model's reading of a pull request, a model answer, and an assistant message. `marked` v12 removed
// its `sanitize` option, so **nothing in the library filters URL schemes**: a `javascript:` href
// written in any of those four is emitted verbatim, and one click runs it in the cockpit's origin.
// The session cookie is `HttpOnly`, so injected script cannot read it — but it is `SameSite=Strict`
// and `Path=/`, so every same-origin `fetch` that script makes carries it. That is the whole API.
//
// The page already overrode marked's `html` renderer, which closes TAG injection completely. This is
// the other half, and it is here rather than in the page for the reason `cockpit/README.md` gives:
// a function that cannot be imported cannot be tested except by reimplementing it. This one is a
// security boundary, so it is the last function in the cockpit that should be untestable.
//
// `base` is a parameter rather than `document.baseURI` because the build refuses a module that
// touches the DOM — and because the tests need to name the base to be about anything.

/** The schemes a rendered document may navigate to. Everything else is refused. */
const SAFE_SCHEMES = ["http:", "https:", "mailto:"];

// Every named character reference whose expansion is a single ASCII character.
//
// The whole set, not the ones that look dangerous: the scheme is what is being protected, and any
// ASCII character can end up in a scheme position. `&colon;`, `&Tab;` and `&NewLine;` are the three
// that were used to walk through this guard, but a list chosen by imagining attacks is the same
// mistake as a deny-list of schemes. The uppercase spellings (`&AMP;`, `&LT;`, `&GT;`, `&QUOT;`) and
// the second names for the same character (`&midast;`, `&lbrack;`, `&vert;`, `&lbrace;`) are here
// for the same reason: a reference this table misses is one the browser still decodes, so it would
// survive normalisation and be decoded *after* the check.
//
// No entry produces a non-ASCII character. `&nbsp;` and its kind are left alone deliberately — they
// cannot contribute a scheme character, and decoding more than the guard needs is its own bug.
const ASCII_NAMED = {
  Tab: "\t", NewLine: "\n",
  excl: "!", quot: '"', QUOT: '"', num: "#", dollar: "$", percnt: "%",
  amp: "&", AMP: "&", apos: "'", lpar: "(", rpar: ")", ast: "*", midast: "*",
  plus: "+", comma: ",", period: ".", sol: "/", colon: ":", semi: ";",
  lt: "<", LT: "<", equals: "=", gt: ">", GT: ">", quest: "?", commat: "@",
  lsqb: "[", lbrack: "[", bsol: "\\", rsqb: "]", rbrack: "]", Hat: "^", lowbar: "_",
  grave: "`", DiacriticalGrave: "`", lcub: "{", lbrace: "{",
  verbar: "|", vert: "|", VerticalLine: "|", rcub: "}", rbrace: "}",
};

// A numeric reference's character, the way the HTML parser produces it: an unpaired surrogate, a
// zero, or anything past the last code point is U+FFFD rather than an invented character.
function fromCode(code) {
  const bad = !(code > 0 && code <= 0x10ffff) || (code >= 0xd800 && code <= 0xdfff);
  return bad ? "\ufffd" : String.fromCodePoint(code);
}

/** How many decoding passes a settled string is allowed to need. See [`asBrowserSeesIt`]. */
const MAX_DECODE_PASSES = 16;

// One pass of the decoding an HTML parser does to an attribute value.
//
// A named reference is decoded only when it ends in `;`. Browsers also decode a handful of legacy
// names without one (`&amp`, `&lt`, `&gt`, `&quot`), but only where the next character is neither
// alphanumeric nor `=`, and none of those four produce a character that can build a scheme — so
// requiring the semicolon costs nothing and keeps this readable. Numeric references are decoded
// with or without it, which is what browsers do.
function decodeOnce(s) {
  return s.replace(
    /&#(\d{1,8});?|&#[xX]([0-9a-fA-F]{1,7});?|&([A-Za-z][A-Za-z0-9]{1,15});/g,
    (whole, dec, hex, name) => {
      if (dec !== undefined) return fromCode(Number(dec));
      if (hex !== undefined) return fromCode(parseInt(hex, 16));
      return Object.prototype.hasOwnProperty.call(ASCII_NAMED, name) ? ASCII_NAMED[name] : whole;
    }
  );
}

/**
 * The string the browser will hand its URL parser, given this href in an attribute.
 *
 * Two transformations, in the order the browser applies them.
 *
 * **Entity decoding, to a fixed point.** This exists because of a bypass in the first version of
 * this guard, found by testing and not by reading: `[c](java&#9;script:alert(1))` was allowed
 * through. `new URL()` refuses `java&#9;script` as a scheme — `&`, `#` and `;` are not scheme
 * characters — so the string parsed as a RELATIVE reference, resolved against the page to `http:`,
 * and passed; the browser then decoded the attribute to `java<TAB>script:` and ran it. The named
 * spellings of the same trick (`java&Tab;script:`, `javascript&colon;`) walked through the fix for
 * it, which decoded numeric references only.
 *
 * It runs to a fixed point rather than once because [`safeHref`] hands this string back to be
 * written into the document: one pass turns `java&amp;#9;script:` into `java&#9;script:`, which is
 * inert in the browser that produced it and live in the one that reads it back. Each pass replaces
 * a reference with a single character, so a pass that changes anything shortens the string — but a
 * README is not obliged to be sane, and `&amp;` nested ten thousand deep would be ten thousand scans
 * of it. Hence [`MAX_DECODE_PASSES`]: past it the string is not settled, and [`safeHref`] refuses
 * rather than guessing which reading the browser will take.
 *
 * **Then what the URL parser discards**: tab, newline and carriage return anywhere in the string,
 * and leading or trailing C0 controls and spaces. Exactly those — an interior space is not removed,
 * because the URL parser percent-encodes it rather than closing the gap, and a normaliser that
 * closed it would turn `http://e.com/a b` into a different address than the one somebody wrote.
 */
function asBrowserSeesIt(href) {
  let s = String(href);
  for (let i = 0; i < MAX_DECODE_PASSES; i++) {
    const next = decodeOnce(s);
    if (next === s) break;
    s = next;
  }
  return s.replace(/[\t\n\r]/g, "").replace(/^[\u0000-\u0020]+|[\u0000-\u0020]+$/g, "");
}

/**
 * The href a rendered document may follow, normalised as the browser will read it — or `null`.
 *
 * An ALLOW-list of schemes, not a deny-list of `javascript:`, for the reason `util::valid_name`
 * gives on the Rust side: a deny-list has to anticipate every scheme a browser will ever navigate,
 * and the next one is always the one nobody listed.
 *
 * Three readings of the string are checked and any one of them being unsafe refuses the link: as
 * written; as the browser will decode it; and that decoding with every ASCII control and space
 * taken out, which is stricter than any browser and is there to catch a separator this code does
 * not know is a separator. A reference with no scheme in a given reading is relative or in-page, and
 * cannot navigate anywhere the page is not already.
 *
 * **The return value is the decoded form, not the string that came in**, and the caller must write
 * it back into the token it came from. Otherwise the guard judges one string and the browser parses
 * another, which is the whole shape of the bypasses above.
 */
function safeHref(raw, base) {
  const href = String(raw ?? "").trim();
  if (!href) return null;
  const seen = asBrowserSeesIt(href);
  if (!seen) return null;
  if (decodeOnce(seen) !== seen) return null; // still decoding after MAX_DECODE_PASSES; not a link
  for (const form of [href, seen, seen.replace(/[\u0000-\u0020\u007f]/g, "")]) {
    if (!form) return null;
    if (!form.includes(":") && !form.startsWith("//")) continue; // relative in this reading
    let scheme;
    try {
      scheme = new URL(form, base).protocol;
    } catch {
      return null; // unparseable is not a URL this page will follow
    }
    if (!SAFE_SCHEMES.includes(scheme)) return null;
  }
  return seen;
}

// ── move.mjs ──
// Whose move is a pull request — across BOTH of your roles — and why, in words.
//
// The queue's `lane` (src/prq.rs) is the REVIEWER's answer: somebody asked you to review this and
// nothing stops you giving it. It is a good answer and it stays. It is not the whole of the
// question the owner asked — "I want to know what needs me very clearly" — because a pull request
// YOU opened is `Lane::Waiting` by definition, however stuck it is (SKEIN-300).
//
// **Where this rule lives, decided rather than defaulted** (SKEIN-302). It is the PAGE's, not the
// server's, for two reasons. The lane answers "is this review work for you" and is a fact about one
// pull request; this answers "does this need your hands", which mixes the roles and is a claim
// about the pane's TOP LEVEL. And every field it reads — `reasons`, `review_threads`, `mergeable`,
// `merge_state`, `review_decision`, `my_review`, `my_review_requested` — is already on the payload,
// so nothing about it needs a request. The last of those is the newest and was added for this rule
// (SKEIN-354): the queue carries GitHub's answer to "is skein still being asked", because the page
// cannot work that out and must not guess at it.
//
// It is a cockpit module rather than a function in the page for the reason `Pr::settled` and
// SKEIN-243 are both records of: **a rule written twice drifts**. Two things read it — the pane's
// grouping and the count the badge is folded from — and neither may be able to disagree with the
// other about what needs you. One function, tested in node.

// A pull request you opened. `reasons` is GitHub's answer to why this is in your queue at all
// (`prq::Reason`), and `author` is the membership rule that put it there; a team reason arrives as
// an object rather than a string, which is why this compares only strings.
const authored = pr => (pr.reasons || []).some(r => r === "author");

// The review threads on a pull request, split into what is open and what could not be seen.
//
// `review_threads` is capped (`REVIEW_THREADS_FETCHED`), so `open` is a FLOOR and `unseen` says by
// how much. That asymmetry is deliberate everywhere it is read: a thread skein can see and that is
// unresolved is evidence, and a thread it never fetched is not — so `unseen` may make a roster say
// it is short, and may never promote a row on a guess.
function threads(pr) {
  const list = pr.review_threads || [];
  const total = pr.review_threads_total;
  return {
    open: list.filter(t => !t.resolved),
    shown: list.length,
    unseen: total != null && total > list.length ? total - list.length : 0,
  };
}

// Does GitHub say this cannot merge as it stands?
//
// `mergeable` is three-valued on purpose (`Pr::mergeable`): `null` is "GitHub has not worked it out
// yet", which is not a conflict and must never be reported as one. It is its own function because
// two callers ask it for OPPOSITE purposes — the author's block below, where a conflict is your
// move, and `moveNote`, where the same conflict on somebody else's branch is only information — and
// a conflict test written twice is how those two come to disagree about what `DIRTY` means.
const conflicted = pr =>
  pr.mergeable === false || (pr.merge_state || "").toUpperCase() === "DIRTY";

// What an authored pull request is waiting on YOU for — `null` when it is waiting on somebody else.
//
// **Checks are not here, and adding them is the change this comment exists to stop.** The owner,
// verbatim (SKEIN-303): "CI pass isn't your responsibility, that is of whoever merges — unless
// ci-queue tag is attached and it fails then. So that differentiation is to be made. But this
// ci-queue thing is very specific to this repo. So I don't want to include that in generic
// workflow." So the generic rule ignores `checks` and `failing_checks` entirely. If the ci-queue
// behaviour is ever wanted it arrives as repo CONFIGURATION handed to this function, never as a
// branch inside it — a red pull request that is nobody's move is the ordinary state of this fleet,
// and a rule that nags about it turns the whole list back into wallpaper.
//
// This does not contradict `Lane::NeedsYou`'s own note about failing checks (src/prq.rs). That one
// is about the REVIEWER's lane — red is the ordinary state of a pull request awaiting review here,
// because CI runs after approval — and it stays exactly as it is. Two different questions about
// one field.
//
// **A pull request you did NOT open never gets here, and a conflict is the case that proves why
// the guard on the first line is load-bearing rather than tidy** (SKEIN-354). The owner, shown
// somebody else's conflicted pull request that skein had put in front of him: "why is it my move at
// all, it is not PR I created, so if there are conflicts that's PR owner problem, not mine. So as
// far as I am concerned my work there is done. You can still say that conflicts or whatever as info
// but it is not mine to fix." Both halves of that are the design. Every reason below is an AUTHOR's
// reason — a conflict is yours to rebase only where the branch is yours — and the same `DIRTY` that
// blocks you here is worth SAYING on a row you are only reading, which is what `moveNote` is for.
// Saying it and claiming him are different pixels.
//
// Ordered most-actionable first, because the row shows one reason and it should be the one you
// would act on: somebody asking for changes outranks a thread, and a thread outranks a rebase.
function authorBlock(pr) {
  if (!authored(pr)) return null;
  if ((pr.review_decision || "") === "CHANGES_REQUESTED") {
    return { kind: "changes", why: "changes requested" };
  }
  const open = threads(pr).open.length;
  if (open) return { kind: "threads", why: `${open} thread${open === 1 ? "" : "s"} unresolved` };
  if (conflicted(pr)) {
    return { kind: "conflict", why: `conflicts with ${pr.base_ref || "its base"}` };
  }
  if ((pr.merge_state || "").toUpperCase() === "BEHIND") {
    return { kind: "behind", why: `behind ${pr.base_ref || "its base"}` };
  }
  // Approved and mergeable is its own quiet state, not a nag: it belongs in the group you go
  // looking at, and `approvalsLine` is what it has to say there.
  return null;
}

// Does your verdict STAND — and has GitHub asked you again since you gave it?
//
// **This asks GitHub, where it used to work the answer out from the commits, and that swap is the
// whole of SKEIN-354.** The old rule also required `review_is_current`: skein compared the sha your
// review was left against with the head that is there now, so any push — a rebase, a typo fix, a
// commit in a file you never look at — took your approval off you and handed the row back. The
// owner, verbatim, on a pull request he had approved that was still claiming him: "approved should
// come only if my review status on the PR is approved rn, if I approved and then some file I own
// changed, so github asks me to review again then it should show that. Can refresh this once in a
// while in background or when I manually refresh."
//
// So there are exactly two questions, and GitHub answers both — skein infers neither:
//
//   * **is your review standing right now** — `my_review`, which `prq::my_review_state` reads from
//     GraphQL's `latestOpinionatedReviews`, so a note you left afterwards does not demote your own
//     approval and an approval GitHub has DISMISSED is gone rather than remembered;
//   * **has GitHub asked you again** — `my_review_requested`, which is you, by name, in
//     `reviewRequests`. That is where a CODEOWNERS re-request lands when a file you own changes,
//     and it is the only re-ask skein acts on. It is a floor and not a census: a request made of a
//     TEAM you are in arrives without your name (and without `read:org`, without the team's either
//     — the roster already reports that blind spot), so the error can only fall on the side of not
//     claiming you, which is the side he asked for.
//
// Why the commit comparison had to go rather than be tuned: measured on the owner's live queue on
// 2026-08-26 (`GET /api/review`, 26 rows), `review_is_current` was false on **all 26** — including
// the two he had approved himself. So this function was false everywhere, no verdict he gave ever
// cleared a row, and the 8 rows where he had said anything at all read "your review is out of
// date" — 7 of them about notes he had left, not verdicts he had given.
//
// A comment is still deliberately not a decision — leaving a note is not clearing the pull request
// — which is the same line `prq`'s lane rule and `my_review_state` both draw.
const decided = pr =>
  (pr.my_review === "approved" || pr.my_review === "changes-requested") && !pr.my_review_requested;

// The pane's top-level bucket for one row: "yours", "theirs", "not-ready" or "archived".
//
// Archived is a HUMAN act and outranks everything — you set it aside, so it does not get to claim
// you back. Not-ready keeps the lane's meaning (a draft or a conflicted pull request somebody else
// is still going to change); an authored one never reaches it, because `prq`'s own lane rule puts
// authorship first. Somebody else's conflicted pull request is exactly what that bucket is for, and
// it is where `moveNote` says so — a row can be told about without being handed to you.
//
// `decided` is asked HERE rather than left to the next refresh because the pane marks a row done in
// place and does not reload (`revMarkDone`, SKEIN-162): between the verdict landing and the next
// queue coming back, `lane` still says `needs-you`, and a list that kept claiming you for a pull
// request you had just approved would be the surface disagreeing with the act you watched it take.
function moveOf(pr) {
  if (pr.lane === "archived") return "archived";
  if (authorBlock(pr)) return "yours";
  if (answered(pr)) return "replied";
  if (pr.lane === "needs-you") return decided(pr) ? "theirs" : "yours";
  return pr.lane === "not-ready" ? "not-ready" : "theirs";
}

// Has somebody answered a finding you left, since you left it? — `docs/pr-review.md` §10's `reply`.
//
// `replied_to_me` is `Pr::replied_to`'s answer, computed server-side where the viewer's login is in
// scope, and it is three-valued on purpose: `true` a reply is there, `false` skein saw the whole
// thread list and there is none, `null`/absent it could not say. Only `true` moves a row, which is
// the same fail-closed rule the engine's facts use — a row must not be pulled back into your hands
// by a fact nobody looked up.
//
// **Above `decided`, and that IS the feature.** A pull request you have approved or asked changes on
// is `theirs` by definition, and it stays there however much the author says to you — which is what
// §10 calls the reply trigger and what the queue could not show. A reply is somebody waiting on you
// again, so it outranks the verdict that sent the row away.
//
// Below `authorBlock`, because a pull request YOU opened that is blocked is already yours and does
// not need a second reason; and below `archived`, because archiving is a human act and nothing
// automatic gets to undo it.
const answered = pr => pr.replied_to_me === true;

// How many of these are your move — the badge's whole number.
//
// It is a function rather than the same filter written at each call site because there are two of
// them and they must not be able to disagree: `loadReview` folds the pane's own fetch into the
// badge the moment the pane loads, and `pollReviewCounts` folds the three-minute poll's rows in
// when nobody has opened it (SKEIN-323). Those two disagreeing IS the bug — the badge counted
// `Lane::NeedsYou` until the pane was opened and then jumped — so the count has one home, next to
// the rule it counts.
// **`replied` counts too**, and it has to. A lane that claims you and is missing from the badge is
// the exact failure the two call sites below were unified to prevent: the surface saying one number
// while the list shows another. A reply you have not answered is work you owe somebody.
const YOUR_MOVE = ["yours", "replied"];
const yourMoveCount = prs =>
  (prs || []).filter(pr => YOUR_MOVE.includes(moveOf(pr))).length;

// Why this row is in the your-move list, in words — "" for a row that is not in it.
//
// The list mixes both roles, which is what makes "review not given" worth saying: on a single-role
// lane it was true of every row and said nothing, and beside "2 threads unresolved" it is the
// difference between work you owe somebody and work somebody owes you. The AGE is deliberately not
// in this sentence — the rail's first cell is the sort key and already carries it (§4).
//
// **"Your review is out of date" is gone, and its absence is the point** (SKEIN-354). That sentence
// was skein's own inference — it fired whenever the head had moved past the sha you reviewed, which
// on the owner's live queue was every row — and it said it about 8 of his 26, seven of them for
// notes he had left rather than verdicts he had given. What replaces it is the only thing that puts
// a decided pull request back in your hands: GitHub asking you again. Reaching that line with a
// verdict on record can mean nothing else, because a standing verdict with no fresh request is
// exactly what `decided` sends to the other list.
function moveWhy(pr) {
  const block = authorBlock(pr);
  if (block) return block.why;
  // A verdict you have given and nobody has asked you to revisit is not a reason to be in this
  // list, and the row must not carry a reason it is not there for: `moveOf` has already sent it to
  // "theirs", and between an approval landing and the next queue arriving `lane` still says
  // `needs-you` (SKEIN-162).
  // Said before the lane is consulted, because a replied row is routinely one `moveOf` has already
  // taken off `needs-you` — a verdict given and answered is the ordinary shape of this.
  if (answered(pr)) return "answered your review";
  if (pr.lane !== "needs-you" || decided(pr)) return "";
  return pr.my_review === "approved" || pr.my_review === "changes-requested"
    ? "asked to review again"
    : "review not given";
}

// What a row that is NOT your move still has to say for itself — "" when it has nothing to add.
//
// Two sentences live here, both of them the owner correcting the pane from live use (SKEIN-354),
// and what they have in common is that a row can carry a fact without the fact carrying a claim.
//
// **A conflict on a pull request somebody else opened**: "You can still say that conflicts or
// whatever as info but it is not mine to fix." So it is said here, on a row in the waiting list,
// and `authorBlock` — the only thing that can put a row in the your-move list for a merge state —
// never sees it, because it is not his branch to rebase.
//
// **An approval whose branch has moved since.** Asked to choose between the row coming back to him
// on the next push and the row staying theirs, he chose theirs until they ask again, in these
// words: WAITING ON OTHERS · you approved · moved since — they have not re-asked. The row is not
// claiming him, and is visibly not having forgotten what he did either — which is what makes the
// quiet answer trustworthy rather than merely quiet.
//
// `review_is_current` is read HERE and nowhere else in this module, and only to say "moved since".
// That is all it is still good for: it is evidence about the CODE — the sha you reviewed against
// the head that is there now — and no longer a verdict about you. Where GitHub named no commit for
// your review it reads the same way, which is the same reading the pane's own "new commits" chip
// has always made of the field.
function moveNote(pr) {
  const move = moveOf(pr);
  if (move === "yours" || move === "archived") return "";
  if (decided(pr)) {
    const said = pr.my_review === "approved" ? "you approved" : "you asked for changes";
    return pr.review_is_current ? said : `${said} · moved since — they have not re-asked`;
  }
  return conflicted(pr) ? `conflicts with ${pr.base_ref || "its base"} — theirs to fix` : "";
}

// Who still owes an approval — "waiting on @dana and @sam", "waiting on the acme/core team".
//
// `review_decision` answers "does this still need somebody"; it cannot answer "who", and who is the
// question an author actually has (SKEIN-306). A team stays a team rather than being flattened to a
// login, because "waiting on @alice" and "waiting on acme/core" are not interchangeable sentences.
function approvalsLine(pr) {
  const asked = (pr.review_requests || []).map(r => (r.team ? `the ${r.name} team` : `@${r.name}`));
  if (!asked.length) return "";
  return `waiting on ${andList(asked)}`;
}

// `a`, `a and b`, `a, b and c`. Its own function because it is read out loud in three places and a
// list joined with commas alone reads as a fragment.
function andList(words) {
  if (words.length <= 1) return words[0] || "";
  return `${words.slice(0, -1).join(", ")} and ${words[words.length - 1]}`;
}

// ── naming.mjs ──
// A box's name, in the browser, agreeing with the one skein computes in Rust.
//
// **A mirror, and mirrors drift** — which is why `src/cockpit.rs` runs this and `util::slug` over
// the same cases and compares. The alternative was asking the server for the name before creating
// the box, and that is a round trip on every keystroke to compute a string neither end disagrees
// about; the alternative to *that* is showing a placeholder shaped like a name, which is how
// somebody ends up creating `thing-<branch>`.
//
// The rule, from `util::slug`: an sbx sandbox name cannot carry every branch character — `/`
// especially — so the *name* is a slug of the branch while the real branch travels in the launch
// spec and reaches `git checkout` intact. Same branch, same name, so reconnect and lookup agree.

function slug(s) {
  let out = "";
  let prevDash = false;
  for (const c of String(s ?? "")) {
    // ASCII alphanumerics only, deliberately: the Rust side asks `is_ascii_alphanumeric`, and a
    // JavaScript `\w` or a unicode-aware test would keep characters it drops — which is a name the
    // browser shows and the fleet does not have.
    if (/[A-Za-z0-9._-]/.test(c) && c.charCodeAt(0) < 128) {
      out += c;
      prevDash = false;
    } else if (!prevDash) {
      out += "-";
      prevDash = true;
    }
  }
  return out.replace(/^-+/, "").replace(/-+$/, "");
}

// `<repo-id>-<branch-slug>`, which is `repos::box_name`.
const boxNameFor = (repoId, branch) => `${repoId}-${slug(branch)}`;

// ── saved.mjs ──
// What `POST /api/fleet/save` came back with, as the one sentence above the list (SKEIN-680).
//
// **The partial case is the only one worth a function.** A save that copied seven boxes out of
// eight has to name the eighth: it is the box whose work is still only inside the sandbox, and it
// is the box a person is about to destroy. "7 boxes saved" is an aggregate the failure fits inside,
// which is the shape this exists to refuse — the same rule the CLI's report keeps, said once here
// so the two surfaces cannot drift into disagreeing about the same run.
//
// An entry is a box that made it out when its `error` is empty; the server sends one entry per box
// either way, and a 200 with failures in it is a real answer rather than a fault.
function savedSummary(boxes) {
  const all = Array.isArray(boxes) ? boxes : [];
  // Not the same as a failure, and not a success either: nothing was asked to happen. Saying "0
  // boxes copied out. Nothing was destroyed" would read as reassurance about an act that did not run.
  if (!all.length) return "no box was copied out.";
  const failed = all.filter(b => b && b.error);
  const done = all.length - failed.length;
  if (!failed.length) {
    return `${done} box${done === 1 ? "" : "es"} copied out to the host. Nothing was stopped and nothing was destroyed.`;
  }
  const names = failed.map(b => (b && b.name) || "an unnamed box").join(", ");
  return `${done} of ${all.length} copied out. ${names} did not — that work is still only inside the sandbox, and a destroy would take it.`;
}

// ── sizes.mjs ──
// Sizes, in the units a person reads.
//
// Two of them, because the server sends bytes for memory and mebibytes for disk, and a single
// formatter taking "a number" is one that eventually gets handed the wrong one.

// Bytes.
const fmtGB = b =>
  b >= 1073741824 ? `${(b / 1073741824).toFixed(1)}G` : `${Math.round(b / 1048576)}M`;

// Mebibytes.
const fmtGb = mb => (mb >= 1024 ? `${(mb / 1024).toFixed(1)}G` : `${mb}M`);

// ── tone.mjs ──
// The identity, as a function: what colour a row is allowed to be, and what the board says it is.
//
// §11.7 settles this once so it is not re-argued per component. The board is **mostly monochrome**,
// and the whole colour budget belongs to one question — *is a human needed?*
//
//   warm   a human is needed
//   cool   the machine is working
//   done   finished, muted green
//   grey   nothing is happening
//
// Four words, learned in one glance. A fifth would spend the budget and mean the first four stop
// being read.
//
// Keyed on `need` and never on `source`, for the reason `queue.rs` merges the two lists server-side:
// a pull request awaiting review and a box awaiting an answer are the same thing to the person
// looking at them, and colouring by which subsystem produced a row is how they stop being.

const TONES = ["warm", "cool", "done", "grey"];

// Every key quoted, including the ones that need no quotes: these are the words the server sends,
// not identifiers, and `src/cockpit.rs` asserts each `Need` variant appears here by its serialised
// tag. A bare key would make that assertion pass on a coincidence.
const BY_NEED = {
  "you": "warm",
  "your-attention": "warm",
  "done": "done",
  "machine": "cool",
  "quiet": "grey",
  "gone": "grey",
};

// An unknown need is grey rather than warm: a row this page has never heard of is not evidence that
// somebody is needed, and the cost of guessing warm is the one thing warm must never become — noise.
const toneOf = need => BY_NEED[need] || "grey";

// Is this row one of the ones the board exists to surface? `standing` counts the same two needs, on
// the server, from the same rows — so this narrows what is shown and never decides the headline.
const needsAHuman = row => toneOf(row && row.need) === "warm";

// The headline for each of the three states (§11.3), and the argument for saying the third out loud:
// a dashboard that looks the same whether or not anything is wrong has failed at its only job, so
// "nothing needs you" is a state with words rather than an empty list nobody notices.
//
// The server decides which state it is, from the rows it built. This only says it in English —
// deriving it here as well would be a second implementation, and the two would disagree on the day
// a rule changes.
function headlineOf(standing) {
  const s = standing || {};
  if (s.standing === "setup-incomplete") {
    const n = s.faults || 0;
    return { tone: "warm", title: `${n} thing${n === 1 ? "" : "s"} to set up`, sub: "the fleet cannot do the thing you came for until this is fixed" };
  }
  if (s.standing === "needs-you") {
    const n = s.rows || 0;
    return { tone: "warm", title: `${n} need${n === 1 ? "s" : ""} you`, sub: "work has stopped and is waiting on you" };
  }
  if (s.standing === "calm") {
    return { tone: "grey", title: "nothing needs you", sub: "everything running is running on its own" };
  }
  // Not a state — the answer has not arrived. Distinct from calm on purpose: "we have not asked yet"
  // and "we asked and nothing is waiting" are the two things this board must never conflate.
  return { tone: "grey", title: "…", sub: "asking" };
}

// ── usage.mjs ──
// What the fleet costs, rendered — SKEIN-835's surface half.
//
// **The whole panel is a pure function of the payload.** `usageHtml` takes the reading, the clock
// and an escaper, and returns markup; the page's job is to fetch, to call this, and to bind one
// button. That is §13's law rather than a preference: the rendering is where every judgement in
// this panel lives — which caveat shows, whether a reading is called stale, what an empty list
// says — and none of it can be tested if it is spelled out inside an `innerHTML` in a 11,700-line
// page.
//
// `esc` is an argument because these modules are concatenated into one script and may not import
// (cockpit/build.mjs refuses one that does). The page's own `esc` (src/web/index.html:1889) is the
// one it is called with, so there is one escaper in the product and no second copy to drift.
//
// **The numbers this was built against**, so the shapes below are not designed on lorem: a fleet
// reading on 2026-09-12 across 16 boxes and 1,313 transcripts came to $30,477.56 over 44.6B tokens,
// of which 98% were cache reads.

// An hour, which is the ceiling the owner set on re-reading: never on page load, on demand, and
// otherwise at most hourly. A reading older than this is still shown — it is the only reading
// there is — but it is shown as old rather than as current.
const USAGE_STALE_SECS = 3600;

// Money. Hand-grouped rather than `toLocaleString`, because the default locale of whoever opens the
// cockpit is not a thing this panel should render differently: `30.477,56` and `30,477.56` are the
// same reading and only one of them can be asserted in a test.
function usd(n) {
  if (n === null || n === undefined || Number.isNaN(Number(n))) return "—";
  const v = Number(n);
  const sign = v < 0 ? "-" : "";
  const [whole, cents] = Math.abs(v).toFixed(2).split(".");
  return `${sign}$${whole.replace(/\B(?=(\d{3})+(?!\d))/g, ",")}.${cents}`;
}

// Exact counts, grouped. Used where the count IS the point — an unpriced model's tokens, the
// number of transcripts read — and a reader who cannot tell 12,345 from 12.3K has lost the fact.
function fmtExact(n) {
  if (n === null || n === undefined || Number.isNaN(Number(n))) return "—";
  return Math.round(Number(n)).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

// Compact counts, for the ones nobody reads digit by digit. Two formatters on purpose, the same
// argument sizes.mjs makes: one that takes "a number" is one that eventually gets handed the wrong
// one, and 44,600,000,000 in a table cell is a number nobody reads at all.
function fmtTok(n) {
  if (n === null || n === undefined || Number.isNaN(Number(n))) return "—";
  const v = Number(n);
  if (Math.abs(v) >= 1e9) return `${(v / 1e9).toFixed(1)}B`;
  if (Math.abs(v) >= 1e6) return `${(v / 1e6).toFixed(1)}M`;
  if (Math.abs(v) >= 1e3) return `${(v / 1e3).toFixed(1)}K`;
  return fmtExact(v);
}

// A share, at the precision the share deserves. Fresh input in this fleet is 0.0017% of all tokens,
// and a fixed two decimals prints that as `0.00%` — which reads as "none" when the true statement
// is "seventeen ten-thousandths of a percent", a different and much more interesting fact.
function usagePct(part, whole) {
  const w = Number(whole);
  if (!w || Number.isNaN(w) || part === null || part === undefined) return "—";
  const p = (Number(part) / w) * 100;
  if (!Number.isFinite(p)) return "—";
  return `${p >= 0.1 ? p.toFixed(2) : Number(p.toPrecision(2))}%`;
}

// How long ago, in words rather than in the board's glyphs.
//
// Deliberately NOT `ago()` from ago.mjs, and the difference is the point rather than an oversight.
// That one labels a row in a dense list and must be four characters wide — `47m ago`. This one ends
// a sentence a person reads once, where "read 47m ago" reads like a machine and "read 47 minutes
// ago" reads like an answer. They format different things for different places; neither is derived
// from the other, so there is no number here that can disagree with one there.
//
// `null` for "we do not know", which is a different statement from "just now" and must never render
// as one — a panel that says a reading is current when it has no idea is the failure this whole
// staleness line exists to prevent.
function usageAge(secs) {
  if (secs === null || secs === undefined || Number.isNaN(Number(secs))) return null;
  const s = Math.max(0, Math.floor(Number(secs)));
  if (s < 45) return "just now";
  if (s < 90) return "a minute ago";
  if (s < 3600) return `${Math.round(s / 60)} minutes ago`;
  if (s < 5400) return "an hour ago";
  if (s < 86400) return `${Math.round(s / 3600)} hours ago`;
  if (s < 172800) return "a day ago";
  return `${Math.round(s / 86400)} days ago`;
}

// What the panel says about its own freshness, from the two fields that carry it.
//
// **Both, not either.** `read_at` is when the reading was taken and `fresh` is the reader's own
// verdict on it, and they can disagree — a reader that failed halfway can produce a reading that is
// two minutes old and known bad. Taking only the clock would call that current; taking only the
// flag would leave a person with no idea how old "not fresh" is. So the age is always said, and the
// flag adds the sentence the age cannot carry.
function usageRead(readAt, fresh, nowMs) {
  const t = Date.parse(readAt || "");
  if (Number.isNaN(t)) {
    return { secs: null, stale: true, text: "skein does not know when this reading was taken" };
  }
  const secs = Math.max(0, Math.floor((Number(nowMs) - t) / 1000));
  const old = secs >= USAGE_STALE_SECS;
  const base = `read ${usageAge(secs)}`;
  if (fresh === false) return { secs, stale: true, text: `${base} — and skein has marked it out of date` };
  return { secs, stale: old, text: old ? `${base} — over an hour old` : base };
}

// ── skein's own reading (SKEIN-1074, SKEIN-1076) ───────────────────────────────────────────────────

// What each of skein's own call sites is called on the page, keyed by the code the payload carries
// (`crate::ai::Site::code`). The words are the owner's, approved under SKEIN-1075, and they are
// the only place these codes become text.
const OWN_SITES = {
  S3: "reviewing a pull request",
  S1: "summarising a pull request",
  S2: "reading a pull request in detail",
  S4: "checking the review read every changed file",
  S5: "answering a check the repository asks for",
  S6: "answering your question about a pull request",
  S7: "drafting a review comment",
  S8: "writing a module note",
  S9: "summarising what a box just did",
  S10: "deciding whether a box's question can be continued",
  S11: "checking the model answers (doctor)",
};

const plural = (n, one, many) => `${fmtExact(n)} ${Number(n) === 1 ? one : many}`;

// The section, above "By box" where it cannot collide with a box that happens to be called skein.
//
// **The per-thing figures cover the same span as the headline total** (the owner's decision on
// SKEIN-1075): everything this reading counted.
function ownHtml(own, esc) {
  const e = esc || (s => String(s));
  const o = own || {};
  const lines = [];
  const r = o.readings || {};
  if (Number(r.finished) > 0) {
    lines.push(`${usd(r.per_finished)} per completed pull-request reading · ${fmtTok(r.tokens_per_finished)} tokens`
      + `   (${plural(r.finished, "reading", "readings")}${
        Number(r.unfinished) > 0 ? `; ${fmtExact(r.unfinished)} that did not finish are counted in` : ""})`);
  } else if (Number(r.unfinished) > 0) {
    lines.push(`no reading finished in this span, so there is nothing to divide by — ${usd(r.cost)} went on ${fmtExact(r.unfinished)} that did not`);
  }
  // The dollars per completed tracker item return here, fleet-wide only, once SKEIN-1139 gives skein
  // a record of when a box held and finished an item. Until then the owner's decision (2026-09-24)
  // is that no tracker line of any kind is drawn — not a reason, not a placeholder.
  if (o.unlabelled_in_boxes) {
    lines.push("calls made before skein labelled its own are counted under the box they ran in");
  }
  const figures = lines.map(l => `<div class="note ug-per">${e(l)}</div>`).join("");

  const sites = (Array.isArray(o.sites) ? o.sites : []).slice().sort((a, b) => b.cost - a.cost);
  if (!Number(o.calls) && !sites.length) {
    return `<div class="note ug-empty">skein made no model calls of its own in this reading</div>` + figures;
  }
  const top = Math.max(...sites.map(x => x.cost), 0);
  const fig = x => `<b>${usd(x.cost)}</b> · ${fmtTok(x.tokens)} tokens · ${plural(x.calls, "call", "calls")}`;
  const row = `<div class="ug-row ug-own">
      <span class="ug-nm">skein's own reading</span>${bar(o.cost, o.cost)}
      <span class="ug-fig">${fig(o)}</span>
    </div>`;
  const breakdown = sites.map(x => `<div class="ug-row ug-site">
      <span class="ug-nm">${e(OWN_SITES[x.site] || x.site)}</span>${bar(x.cost, top)}
      <span class="ug-fig">${fig(x)}</span>
    </div>`).join("");
  return row + breakdown + figures;
}

// ── the panel ─────────────────────────────────────────────────────────────────────────────────────

const bar = (v, max) =>
  `<span class="ug-bar"><i style="width:${max > 0 ? Math.max(1, Math.round((Math.min(1, v / max)) * 100)) : 0}%"></i></span>`;

const section = (title, rows, empty) =>
  `<div class="ug-h">${title}</div>` + (rows || `<div class="note ug-empty">${empty}</div>`);

/** The whole panel, as markup.
 *
 * `u` is the reading (`null` before there has ever been one). `nowMs` is the clock, passed in so
 * the staleness line is a function of its arguments and can be asserted at a chosen instant.
 * `note` is an optional line the page puts under the head — it is how a failed request is said,
 * and it is a parameter rather than a field on `u` because the payload's shape belongs to the
 * reader lane and this panel does not get to add to it.
 */
function usageHtml(u, nowMs, esc, note) {
  const e = esc || (s => String(s));
  const refresh = `<button type="button" class="kbtn ug-refresh" id="ug-refresh">Refresh</button>`;
  const hint = note ? `<div class="ug-note">${e(note)}</div>` : "";

  if (!u || !u.totals) {
    // Never a zero. A fleet that has not been read and a fleet that cost nothing look identical the
    // moment this renders `$0.00`, and of the two the wrong one is the one a person would believe.
    return `<div class="ug-head"><span class="ug-cost">not read yet</span>
      <span class="ug-when">Refresh asks each box for its own transcripts — nothing is read on page load</span>
      ${refresh}</div>${hint}`;
  }

  const t = u.totals;
  const read = usageRead(u.read_at, u.fresh, nowMs);

  const head = `<div class="ug-head">
    <span class="ug-cost">${usd(t.cost)}</span>
    <span class="ug-when${read.stale ? " stale" : ""}">${e(read.text)}</span>
    ${refresh}
    <span class="ug-sub">${fmtTok(t.tokens)} tokens · ${fmtExact(u.boxes_read)} boxes · ${fmtExact(u.transcripts_read)} transcripts${
      u.prices_as_of ? ` · prices as of ${e(u.prices_as_of)}` : ""}</span>
  </div>`;

  // The caveat, always drawn — the empty case included.
  //
  // A model the price table did not know contributes tokens and no dollars, so its cost silently
  // reads as zero and the fleet total reads as a cheaper month than it was. That is a wrong answer
  // wearing the clothes of a right one, and the only defence is to say so on screen. The empty list
  // is drawn too, because "no unpriced models" and "this panel does not check" are indistinguishable
  // when the row is simply absent, and a reader cannot tell which silence they are looking at.
  const un = Array.isArray(u.unpriced) ? u.unpriced : [];
  const unpriced = un.length
    ? `<div class="ug-caveat bad"><span class="ug-mark">!</span><span class="ug-ctext">
         <b>${fmtExact(un.length)} model${un.length === 1 ? "" : "s"} had no price</b> — the tokens are
         counted, the dollars are not, so the total above is a floor rather than the bill:
         ${un.map(m => `${e(m.model)} (${fmtExact(m.tokens)} tokens)`).join(", ")}.
       </span></div>`
    : `<div class="ug-caveat ok"><span class="ug-mark">✓</span><span class="ug-ctext">
         every model in this reading had a price, so no tokens are counted at zero.
       </span></div>`;

  // The insight, on screen rather than in a `title`.
  //
  // Put in the open deliberately, and SKEIN-486's incident is the reason: every detail of the health
  // report used to live in a `title` attribute — uncopyable, invisible on a phone, gone on scroll —
  // and moving it into the pane is what made it readable. A panel that shows only dollars invites
  // exactly one conclusion, "write shorter prompts", and this line is the evidence that the
  // conclusion is wrong: almost the whole bill is context replayed on every turn.
  const insight = `<div class="ug-insight">
    <b>${usagePct(t.cache_read, t.tokens)}</b> of these tokens are cache reads — the conversation so
    far, re-sent on every turn — against ${usagePct(t.output, t.tokens)} written by the model and
    ${usagePct(t.input, t.tokens)} typed as fresh input. The bill follows how much context a turn
    carries and how many turns there are, not how much anyone types.
  </div>`;

  const boxes = (Array.isArray(u.boxes) ? u.boxes : []).slice().sort((a, b) => b.cost - a.cost);
  const topBox = Math.max(...boxes.map(b => b.cost), 0);
  const boxRows = boxes.map(b => {
    const mix = Object.entries(b.models || {}).sort((x, y) => y[1] - x[1])
      .map(([m, c]) => `${e(m)} ${usd(c)}`).join(" · ");
    return `<div class="ug-row">
      <span class="ug-nm">${e(b.box)}</span>${bar(b.cost, topBox)}
      <span class="ug-fig"><b>${usd(b.cost)}</b> · ${fmtTok(b.tokens)}${
        b.days ? ` · ${fmtExact(b.days)}d` : ""}${
        b.first && b.last ? ` · ${e(b.first)}→${e(b.last)}` : ""}</span>
      ${mix ? `<span class="ug-mix">${mix}</span>` : ""}
    </div>`;
  }).join("");

  const months = (Array.isArray(u.months) ? u.months : []).slice().sort((a, b) => String(a.month).localeCompare(String(b.month)));
  const topMonth = Math.max(...months.map(m => m.cost), 0);
  const monthRows = months.map(m => `<div class="ug-row">
      <span class="ug-nm">${e(m.month)}</span>${bar(m.cost, topMonth)}
      <span class="ug-fig"><b>${usd(m.cost)}</b> · ${fmtTok(m.tokens)}${
        m.cache_read !== undefined && m.tokens ? ` · ${usagePct(m.cache_read, m.tokens)} cache` : ""}</span>
    </div>`).join("");

  const models = (Array.isArray(u.models) ? u.models : []).slice().sort((a, b) => b.cost - a.cost);
  const topModel = Math.max(...models.map(m => m.cost), 0);
  const modelRows = models.map(m => `<div class="ug-row">
      <span class="ug-nm">${e(m.model)}</span>${bar(m.cost, topModel)}
      <span class="ug-fig"><b>${usd(m.cost)}</b> · ${fmtTok(m.tokens)}</span>
    </div>`).join("");

  // The daily series is the only thing here that shows a direction rather than a position, which is
  // why it gets a shape instead of a table. The hover carries the exact day; the busiest one is
  // named in words underneath, because a fact that exists only in a `title` is a fact on a phone
  // nobody has.
  const daily = (Array.isArray(u.daily) ? u.daily : []).slice().sort((a, b) => String(a.day).localeCompare(String(b.day)));
  const topDay = Math.max(...daily.map(d => d.cost), 0);
  const busiest = daily.slice().sort((a, b) => b.cost - a.cost)[0];
  const busiestBox = busiest && Object.entries(busiest.by_box || {}).sort((x, y) => y[1] - x[1])[0];
  const dayStrip = daily.length
    ? `<div class="ug-days">${daily.map(d =>
        `<span class="ug-day" title="${e(d.day)} · ${usd(d.cost)}"><i style="height:${
          topDay > 0 ? Math.max(2, Math.round((d.cost / topDay) * 100)) : 0}%"></i></span>`).join("")}</div>`
      + `<div class="ug-dfoot">${fmtExact(daily.length)} day${daily.length === 1 ? "" : "s"} of spend`
      + (busiest ? `, the heaviest ${e(busiest.day)} at ${usd(busiest.cost)}` : "")
      + (busiestBox ? ` — most of it ${e(busiestBox[0])}, ${usd(busiestBox[1])}` : "")
      + `.</div>`
    : "";

  return head + hint + unpriced + insight
    + `<div class="ug-h">skein's own reading</div>` + ownHtml(u.own, e)
    + section("By box", boxRows, "no box reported a reading")
    + section("By month", monthRows, "no month in this reading")
    + section("By model", modelRows, "no model in this reading")
    + section("By day", dayStrip, "no daily series in this reading");
}

